        while True:
            # Simplify clauses under current assignment.
            simplified = []
            unit = None
            for clause in clauses:
                new_clause = []
                satisfied = False
                for lit in clause:
                    v = abs(lit)
                    if v in assignment:
                        if assignment[v] == (lit > 0):
                            satisfied = True
                            break
                    else:
                        new_clause.append(lit)
