            if unit is None:
                break
            assignment = dict(assignment)
            assignment[abs(unit)] = unit > 0
        if not clauses:
            return True
        # Choose the variable occurring most often.
        counts = {}
        for clause in clauses:
            for lit in clause:
                counts[abs(lit)] = counts.get(abs(lit), 0) + 1
